// The Durable Object replays the SAME migration files as the PC server (apps/api/drizzle), checks and data
// fixes included. This writes src/migrations.gen.ts, which imports each .sql file as text (wrangler "Text" rule).
import fs from 'node:fs';
import path from 'node:path';
const drizzleDir = path.resolve(import.meta.dirname, '..', '..', 'api', 'drizzle');
const journal = JSON.parse(fs.readFileSync(path.join(drizzleDir, 'meta', '_journal.json'), 'utf8'));
const key = (idx) => `m${String(idx).padStart(4, '0')}`;
const lines = [
  '// Generated by scripts/gen-migrations.mjs from apps/api/drizzle: do not edit.',
  "import journal from '../../api/drizzle/meta/_journal.json';",
  ...journal.entries.map((e) => `import ${key(e.idx)} from '../../api/drizzle/${e.tag}.sql';`),
  '',
  `export default { journal, migrations: { ${journal.entries.map((e) => key(e.idx)).join(', ')} } };`,
  '',
];
fs.writeFileSync(path.resolve(import.meta.dirname, '..', 'src', 'migrations.gen.ts'), lines.join('\n'));
console.log(`migrations.gen.ts: ${journal.entries.length} migrations`);
